@dataclass(frozen=True)
class RecoveryReport:
    """Outcome of an error-share-aware secret reconstruction.

    ``secret`` is the constant term of the deciding polynomial, the same
    value :func:`reconstruct_secret` yields on the accepted shares.
    ``accepted`` holds the shares that lie on the deciding polynomial and
    ``rejected`` every other share; both tuples are ordered by strictly
    increasing coordinate. The dataclass is frozen, positionally
    constructible and compared by value.
    """

    secret: int
    accepted: tuple[Share, ...]
    rejected: tuple[Share, ...]


def _lagrange_constant_at_zero(points: Sequence[Share], prime: int) -> int:
    """Constant term of the degree-``len(points) - 1`` interpolant of ``points``."""
    return reconstruct_secret(points, prime=prime)


def recover_secret(
    shares: Iterable[Share] | Sequence[Share],
    threshold: int,
    *,
    prime: int = DEFAULT_PRIME,
) -> RecoveryReport:
    """Rebuild the secret while identifying tampered shares.

    Every ``threshold``-sized subset of the shares interpolates a candidate
    polynomial of degree below ``threshold``. The candidate fitting the most
    shares decides: shares it fits are accepted, the rest rejected, and its
    value at ``x = 0`` is the recovered secret. The decision depends only on
    the share contents and ``threshold``, never on submission order.

    A tie between candidates fitting the same maximal number of shares, or a
    best candidate fitting fewer than ``threshold`` shares, leaves the secret
    ambiguous and raises ``ValueError``.
    """
    if not isinstance(threshold, int) or isinstance(threshold, bool):
        raise TypeError("threshold must be an integer")
    if not isinstance(prime, int) or isinstance(prime, bool):
        raise TypeError("prime must be an integer")
    if isinstance(shares, (str, bytes)) or not isinstance(
        shares, (Iterable,) and (list, tuple)
    ):
        # Reject non-containers up front; a one-pass generator would be
        # consumed by validation and unavailable for the subset enumeration.
        if not isinstance(shares, (list, tuple)):
            raise TypeError("shares must be a tuple or list of Share instances")
    materialised = list(shares)
    if not materialised:
        raise ValueError("at least one share is required")
    for share in materialised:
        if not isinstance(share, Share):
            raise TypeError("shares must be Share instances")
        if not 0 < share.x < prime:
            raise ValueError("share index must satisfy 0 < x < prime")
        if not 0 <= share.y < prime:
            raise ValueError("share value must satisfy 0 <= y < prime")
    indices = [share.x for share in materialised]
    if len(set(indices)) != len(indices):
        raise ValueError("duplicate share index")
    if threshold < 1:
        raise ValueError("threshold must be at least 1")
    if threshold > len(materialised):
        raise ValueError("threshold must not exceed the number of shares")
    if not _is_prime(prime):
        raise ValueError("prime must be prime")

    ordered = sorted(materialised, key=lambda share: share.x)

    if threshold == 1:
        # Each share votes for the constant polynomial through it; every
        # share with the same value belongs to the same candidate.
        votes: dict[int, list[Share]] = {}
        for share in ordered:
            votes.setdefault(share.y, []).append(share)
        best_value = max(votes, key=lambda value: len(votes[value]))
        winners = [value for value, group in votes.items() if len(group) == len(votes[best_value])]
        if len(winners) > 1:
            raise ValueError("ambiguous recovery: multiple polynomials fit the most shares")
        accepted = tuple(votes[best_value])
        rejected = tuple(share for share in ordered if share not in accepted)
        return RecoveryReport(best_value, accepted, rejected)

    # Enumerate the distinct candidate polynomials via every threshold-sized
    # subset; subsets drawn from the same underlying polynomial interpolate
    # the same constant term, which is how they are deduplicated.
    candidates: dict[int, set[int]] = {}
    for subset in combinations(ordered, threshold):
        secret = _lagrange_constant_at_zero(subset, prime)
        fit = {
            share.x
            for share in ordered
            if reconstruct_secret(list(subset), prime=prime) == secret
            and _point_on_polynomial(share, subset, prime)
        }
        candidates.setdefault(secret, set()).update(
            share.x
            for share in ordered
            if _point_on_polynomial(share, subset, prime)
        )

    best_count = max(len(fit) for fit in candidates.values())
    if best_count < threshold:
        raise ValueError("not enough consistent shares to recover the secret")
    best_secrets = [secret for secret, fit in candidates.items() if len(fit) == best_count]
    if len(best_secrets) > 1:
        raise ValueError("ambiguous recovery: multiple polynomials fit the most shares")

    best_fit = candidates[best_secrets[0]]
    accepted = tuple(share for share in ordered if share.x in best_fit)
    rejected = tuple(share for share in ordered if share.x not in best_fit)
    return RecoveryReport(best_secrets[0], accepted, rejected)


def _point_on_polynomial(
    point: Share, points: Sequence[Share], prime: int
) -> bool:
    """Whether ``point`` lies on the degree-``len(points) - 1`` interpolant."""
    return reconstruct_secret(list(points) + [point], prime=prime) == reconstruct_secret(
        points, prime=prime
    ) and evaluate_at(
        _interpolating_coefficients(points, prime), point.x, prime
    ) == point.y


def _interpolating_coefficients(points: Sequence[Share], prime: int) -> list[int]:
    """Coefficients, constant term first, of the interpolant of ``points``."""
    coefficients: list[int] = [0]
    for share in points:
        # Newton-style accumulation of one Lagrange basis contribution.
        numerator_polynomial: list[int] = [share.y]
        denominator = 1
        for other in points:
            if other.x == share.x:
                continue
            numerator_polynomial = _polynomial_add_scaled(
                _polynomial_multiply_linear(numerator_polynomial, -other.x, prime),
                [0],
                0,
                prime,
            )
            denominator = denominator * (share.x - other.x) % prime
        scale = share.y * pow(denominator, -1, prime) % prime
        basis = [1]
        for other in points:
            if other.x == share.x:
                continue
            basis = _polynomial_multiply_linear(basis, -other.x, prime)
        coefficients = [
            (a + scale * b) % prime for a, b in zip_longest(coefficients, basis, fillvalue=0)
        ]
    return coefficients


def _polynomial_multiply_linear(
    coefficients: Sequence[int], constant: int, prime: int
) -> list[int]:
    """Multiply the polynomial by ``(x + constant)`` modulo ``prime``."""
    raised = [0] + [c % prime for c in coefficients]
    shifted = [c * constant % prime for c in coefficients] + [0]
    return [(a + b) % prime for a, b in zip_longest(raised, shifted, fillvalue=0)]


def _polynomial_add_scaled(
    left: Sequence[int], right: Sequence[int], scale: int, prime: int
) -> list[int]:
    return [
        (a + scale * b) % prime
        for a, b in zip_longest(left, right, fillvalue=0)
    ]


def evaluate_at(coefficients: Sequence[int], x: int, prime: int) -> int:
    return evaluate_polynomial(coefficients, x, prime=prime)


